/**
 * The create/edit screen (`design/archetypes/form-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { claimSlot, createDerived, elementRef, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/form-page.module.css'
import Inline from '../layout/Inline'
import PageHeader from '../structure/PageHeader'

export interface FormPageProps {
  /**
   * The submit row, with exactly one `solid` Button and quieter variants for the rest.
   */
  actions: JSX.Element
  /**
   * Cards of FormFields.
   */
  children: JSX.Element
  description?: string
  onSubmit?: () => void
  title: string
}

/** The create/edit screen. */
export default function FormPage(given: FormPageProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const form = elementRef<HTMLElement>()
    const submit = createDerived(() => (event: Event) => {
      event.preventDefault()
      const invalid = form.value?.querySelector<HTMLElement>('[aria-invalid="true"]')
      if (invalid) {
        invalid.focus()
        return
      }
      props.onSubmit?.()
    })
    return (
      <div class={styles.page} data-member="form-page">
        <PageHeader title={props.title} description={props.description} />
        {props.onSubmit !== undefined ? (
          <form
            class={styles.form}
            novalidate={true}
            onsubmit={($event: SubmitEvent) => submit.value($event)}
            ref={form.attach}
          >
            {props.children}
            {/* actions */}
            <div class={styles.actions}>
              <Inline gap={3} justify="end" wrap={true}>
                {props.actions}
              </Inline>
            </div>
          </form>
        ) : (
          <>
            {props.children}
            {/* actions */}
            <div class={styles.actions}>
              <Inline gap={3} justify="end" wrap={true}>
                {props.actions}
              </Inline>
            </div>
          </>
        )}
      </div>
    )
  })
}
